const lessons=[{"sentences":[{"speaker":"A","text":"Welcome everyone to the annual city garden festival and thank you for offering your valuable time today.","position":1,"audioStartSeconds":0,"audioEndSeconds":6.255},{"speaker":"A","text":"Before you begin your shifts please listen carefully to these important safety guidelines and daily schedules.","position":2,"audioStartSeconds":6.455,"audioEndSeconds":12.962333333333333},{"speaker":"A","text":"All volunteers must register at the main entrance desk by eight thirty in the morning.","position":3,"audioStartSeconds":13.162333333333333,"audioEndSeconds":18.472791666666666},{"speaker":"A","text":"You will receive your official identification badge and a bright yellow jacket after signing in.","position":4,"audioStartSeconds":18.672791666666665,"audioEndSeconds":24.342875},{"speaker":"A","text":"Your primary morning task involves guiding visitors toward the central stage area and the flower exhibition.","position":5,"audioStartSeconds":24.542875,"audioEndSeconds":31.16658333333333},{"speaker":"A","text":"If someone asks for directions to the cafeteria you should point them toward the northern food court.","position":6,"audioStartSeconds":31.366583333333335,"audioEndSeconds":37.204208333333334},{"speaker":"A","text":"We scheduled a mandatory twenty minute coffee break at eleven oclock for every single team member.","position":7,"audioStartSeconds":37.40420833333334,"audioEndSeconds":43.512458333333335},{"speaker":"A","text":"You can enjoy free sandwiches and bottled water inside the staff lounge located behind the greenhouse.","position":8,"audioStartSeconds":43.71245833333333,"audioEndSeconds":50.32329166666667},{"speaker":"A","text":"After lunch afternoon duties will change because some volunteers will help clear rubbish from pathways.","position":9,"audioStartSeconds":50.523291666666665,"audioEndSeconds":56.683083333333336},{"speaker":"A","text":"Please wear your thick protective gloves whenever you handle heavy waste bags or garden clippings.","position":10,"audioStartSeconds":56.88308333333333,"audioEndSeconds":62.7715},{"speaker":"A","text":"If you experience any sudden medical emergency during your shift do not try to handle it alone.","position":11,"audioStartSeconds":62.9715,"audioEndSeconds":68.99029166666666},{"speaker":"A","text":"Instead you should immediately contact the event supervisor using the emergency number printed on your badge.","position":12,"audioStartSeconds":69.19029166666667,"audioEndSeconds":75.63358333333333},{"speaker":"A","text":"At the end of the day please return your yellow jacket to the registration desk before leaving.","position":13,"audioStartSeconds":75.83358333333334,"audioEndSeconds":81.36195833333333},{"speaker":"A","text":"Thank you once again for your wonderful support and have a fantastic time helping out today.","position":14,"audioStartSeconds":81.56195833333334,"audioEndSeconds":87.0485}],"questions":[{"prompt":"Registration time: ______","answer":"eight thirty","evidenceSentence":3,"evidence":"eight thirty","explanation":"Người nói thông báo tình nguyện viên phải đăng ký lúc tám giờ rưỡi."},{"prompt":"Provided outer clothing: ______","answer":"yellow jacket","evidenceSentence":4,"evidence":"yellow jacket","explanation":"Tình nguyện viên nhận được huy hiệu và một chiếc áo khoác màu vàng sau khi ký tên."},{"prompt":"Morning task location: ______","answer":"central stage","evidenceSentence":5,"evidence":"central stage","explanation":"Nhiệm vụ buổi sáng là hướng dẫn khách đến khu vực sân khấu trung tâm."},{"prompt":"Break duration: ______","answer":"twenty minute","evidenceSentence":7,"evidence":"twenty minute","explanation":"Ban tổ chức sắp xếp giờ nghỉ giải lao kéo dài hai mươi phút vào lúc mười một giờ."},{"prompt":"Afternoon duty: ______","answer":"clear rubbish","evidenceSentence":9,"evidence":"clear rubbish","explanation":"Nhiệm vụ buổi chiều thay đổi vì một số tình nguyện viên sẽ giúp dọn rác khỏi các lối đi."},{"prompt":"Emergency contact method: ______","answer":"emergency number","evidenceSentence":12,"evidence":"emergency number","explanation":"Tình nguyện viên được yêu cầu liên hệ với giám sát viên bằng số khẩn cấp in trên huy hiệu."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
